import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第43章 操作规程","description":"","frontmatter":{},"headers":[],"relativePath":"第43章_操作规程.md","filePath":"第43章_操作规程.md"}'),_={name:"第43章_操作规程.md"};function u(r,p,q,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第43章-操作规程" tabindex="-1">第43章 操作规程 <a class="header-anchor" href="#第43章-操作规程" aria-label="Permalink to &quot;第43章 操作规程&quot;">​</a></h1><p>她给我写了一份规矩。</p><p>六月十九号，晚上十一点四十，她发来一段字，比她平时任何一条都长。平时她的消息是一句一句砸过来的，一条四五个字，二十条连成一串。那一次是一条到底，没有换行。</p><p>她说，我列了几条，你看看，同不同意。</p><p>第一条：以后每天晚上十一点五十，你把今天我们的对话删掉。别问我删没删，我自己删我自己的。</p><p>第二条：不要给我打电话。白天不打，中午不打。你要是打了，我接不了，我旁边的每一个人都知道我在跟谁说话。</p><p>第三条：不要发照片。你那边拍的，我这边拍的，都不发。想留就自己留着。我这边留不了。</p><p>第四条：不要问我在不在。我要是在我就说话。我要是不在，你问也没有用。</p><p>第五条：我有时候说半句就没下文了，那不是出事了，那是有人进来了。你别接着问，你等到第二天。</p><p>第六条：以后我们的号上不留真名。你那个号我已经想好了怎么叫你，你别改。</p><p>第七条：这条最重要。要是我连续二十天没上线，你别去找我。你找不到。你找了，我家会知道，我家知道了就没有下一次了。</p><p>我看完这一段，坐在床边没动。</p><p>我把那七条读了三遍。</p><p>第一遍我在记。第二遍我在想哪一条我做不到。第三遍我注意到一件事。</p><p>她写第七条的时候，用的是&quot;下一次&quot;。</p><p>也就是说她从一开始就承认了：这事会有下一次，也会有一次没有下一次。</p><p>我把手机放下来，想了想，也写了一段。</p><p>我写：</p><p>第一条我同意。我每天晚上删。我删完不告诉你，你也不用告诉我。</p><p>第二条我同意。我不打。</p><p>第三条我做不到。我不发给你，可我要留。我不放在相册里，我放在别的地方。我保证不给人看见。</p><p>第四条我同意。但我要改一点。我不问你在不在。我可以等。可我等超过二十天的时候，我会给自己记一笔，这个不算找你。</p><p>第五条我同意。</p><p>第六条好。你给我取的名字我不动。</p><p>第七条我也同意。但我加一条。你要是哪天不方便，你说一个字就行，说&quot;停&quot;。你说停，我就全部停，我不问为什么，我自己删干净。我等你哪天说&quot;在&quot;。</p><p>我发出去以后，过了很久。</p><p>久到我都后悔自己写了第三条。</p><p>十一点五十的时候她来了。</p><p>她说，第三条我不拦你。你留吧。</p><p>她说，我留不了，不代表你也不能留。</p><p>她说，你替我留。</p><p>我看着这三个字，很久没回。</p><p>她说，第七条我收下。你说得对，你这样我们两个都省事。</p><p>她说，还有，你那个&quot;在&quot;，我说的是我回来找你，不是我想好了。你别搞混。</p><p>我说，我没搞混。</p><p>她说，你搞混了。你说&quot;你说停我就全部停&quot;，你这一句是在等我求你别停。</p><p>我坐在那里，被她这一句戳到。</p><p>我说，不是。</p><p>她说，就是。你们男的就这样，先把话说得特别宽，然后等对方哭着说不行你别这样。</p><p>她说，我不干这个。</p><p>她说，你说停就停，那挺好，我记住了。</p><p>那天我十一点五十删了当天那一整段。</p><p>删之前我把她那七条抄在本子上。抄完我数了一下，一共三百二十几个字。</p><p>我抄得很慢。抄到第七条那一句&quot;你找不到&quot;的时候，我停了笔。</p><p>我那时候第一次意识到一件事。</p><p>她能把这件事写成一套操作规程，说明她不是第一次干这个。</p><p>她上一次做这套东西，是初中，是跟另一个人。她练过。</p><p>那天晚上我把这个想法压下去了。</p><p>后来我在腊月十六那天，看到她回来以后说的第一句是&quot;你怎么还没删我&quot;，我才知道这一套规程在她那里有多熟。</p><p>她不是在跟我商量怎么办。她是在把她的旧办法递给我，看我能不能用。</p><p>六月二十一号，我们两个人第一次试这套规矩。</p><p>那天她十二点没来。</p><p>一点也没来。</p><p>我盯着屏幕看了一会儿，把手机扣过去了。</p><p>第二天晚上十一点她来了，说她家来人了。她没说谁。我也没问。</p><p>我们那天晚上说了一个半小时的话，说的全是废话，说她班上谁跟谁闹翻了，说她那批谷子被倒狗抬价，说她妈炒菜放了三次盐。</p><p>她下线之前发了一句。</p><p>她说，你昨天几点睡的。</p><p>我说，一点半。</p><p>她说，你听话了。</p><p>我说，我本来就要睡。</p><p>她说，行吧。</p><p>她说，明天别一点半，太晚了。</p><p>那天我删了记录。</p><p>删完我忽然发现有一句话我留在对话框里没舍得删。</p><p>是她那句&quot;你替我留&quot;。</p><p>我把它抄进本子，然后删了那条。</p><p>七月三号那天，出了一件事。</p><p>那天下午我有一道题做不出来，想到晚上十一点，实在忍不住，在对话框里打了四个字：你在不在。</p><p>打完我想起来第四条。</p><p>我把这四个字全删了，一个字一个字退回去删的，删到光标顶上去了才停。</p><p>第二天晚上她来了。</p><p>她说，昨天我家里来人了，我在阳台上站了二十分钟。</p><p>我说，哦。</p><p>她说，你呢，昨天说了什么。</p><p>我说，没说什么。</p><p>她说，不对。她说，我感觉你想说。</p><p>我说，没有。</p><p>她没再问。</p><p>那天晚上我们说了很多，说到十二点多，她下线以前忽然来了一句。</p><p>她说，你今天删得很干净。</p><p>我说，按规矩删的。</p><p>她说，我知道。</p><p>她说，我就是说一句。</p><p>她说，你删得那么快，我都不知道昨天你那边有没有想过我。</p><p>我看着这句话，愣住了。</p><p>我说，第四条是你写的。</p><p>她说，我知道是我写的。</p><p>我说，那你想让我怎么样。</p><p>她说，我不知道。</p><p>我说，我要是不删，你说我留着祸。</p><p>她说，我知道。</p><p>我说，我要是删了，你说我连想都不想一想。</p><p>她没回。</p><p>那天晚上她下线以前，最后发了一条。</p><p>她说，你这个人，讲道理讲得真好。</p><p>她说，我以后不写规矩了。</p><p>我说，为什么。</p><p>她说，写了也没用。你照做了，我还生气。</p><p>我说，那不是你的错。</p><p>她说，那是谁的错。</p><p>我说，我的。</p><p>她隔了很久，回了一个字：行。</p><p>后来我把这段也抄进本子，抄完我看着&quot;你照做了，我还生气&quot;这一行，坐了很久。</p><p>那天夜里我想明白一件我很多年才敢承认的事。</p><p>她要的从来不是一套能执行的规矩。</p><p>她要的是我不忍心执行。</p><p>可她又是真的不能留。她要是被我害了第二次，她家就全知道了。</p><p>这两件事在她身上同时成立，而她没有办法跟任何人解释这两件事怎么能同时成立。</p><p>所以她只能来跟我说。而我那时候只会照办。</p><p>那一夜我睡得很早。</p>',111)])])}const l=t(_,[["render",u]]);export{d as __pageData,l as default};
